import { useEffect, useState } from "react";
import { healthResponseSchema, type HealthResponse } from "@auto-apply/shared";
import { API_URL } from "./api";
import { RunPanel } from "./run/RunPanel";

type State =
  | { kind: "loading" }
  | { kind: "error"; message: string }
  | { kind: "ready"; health: HealthResponse };

export function App() {
  const [state, setState] = useState<State>({ kind: "loading" });

  useEffect(() => {
    let cancelled = false;

    fetch(`${API_URL}/api/health`)
      .then(async (res) => {
        if (!res.ok) {
          throw new Error(`API responded ${res.status}`);
        }
        return healthResponseSchema.parse(await res.json());
      })
      .then((health) => {
        if (!cancelled) {
          setState({ kind: "ready", health });
        }
      })
      .catch((err: unknown) => {
        if (!cancelled) {
          setState({
            kind: "error",
            message: err instanceof Error ? err.message : "Unknown error",
          });
        }
      });

    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <main>
      <h1>AI Auto-Apply</h1>
      <RunPanel />
      {state.kind === "loading" && <p role="status">Checking API…</p>}
      {state.kind === "error" && <p role="alert">Could not reach the API: {state.message}</p>}
      {state.kind === "ready" && (
        <dl>
          <dt>API status</dt>
          <dd>{state.health.status}</dd>
          <dt>Service</dt>
          <dd>{state.health.service}</dd>
          <dt>Namespace</dt>
          <dd>{state.health.namespace}</dd>
          <dt>Storage</dt>
          <dd>
            {state.health.repo === "memory" ? "In-memory (not persisted)" : "Firestore"}
          </dd>
        </dl>
      )}
    </main>
  );
}
import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { App } from "./App";

const rootElement = document.getElementById("root");
if (!rootElement) {
  throw new Error("Root element #root not found");
}

createRoot(rootElement).render(
  <StrictMode>
    <App />
  </StrictMode>,
);
/**
 * The browser's calls to the API, each response parsed with the shared
 * contract. Credentials ride every call so the auth cookie (ticket 15) works
 * cross-origin in dev.
 */
import {
  activeRunResponseSchema,
  createRunResponseSchema,
  errorResponseSchema,
  type Run,
} from "@auto-apply/shared";

// In dev the web app (5173) calls the API (3001) cross-origin; in production the
// same origin serves both and nginx proxies /api, so VITE_API_URL is "".
export const API_URL = import.meta.env.VITE_API_URL ?? "http://localhost:3001";

/** A non-2xx answer, carrying the contract's error code when there is one. */
export class ApiError extends Error {
  constructor(
    readonly status: number,
    readonly code: string | null,
    message: string,
  ) {
    super(message);
    this.name = "ApiError";
  }
}

async function readJson(res: Response): Promise<unknown> {
  if (res.ok) return res.json();
  const body = errorResponseSchema.safeParse(await res.json().catch(() => null));
  throw new ApiError(
    res.status,
    body.success ? body.data.error.code : null,
    body.success ? body.data.error.message : `API responded ${res.status}`,
  );
}

/** `POST /api/runs`: starts a Run; an `ApiError` with code `run_active` on 409. */
export async function startRun(): Promise<string> {
  const res = await fetch(`${API_URL}/api/runs`, { method: "POST", credentials: "include" });
  return createRunResponseSchema.parse(await readJson(res)).runId;
}

/** `GET /api/runs/active`: the Run to reattach to after a refresh, if any. */
export async function getActiveRun(): Promise<Run | null> {
  const res = await fetch(`${API_URL}/api/runs/active`, { credentials: "include" });
  return activeRunResponseSchema.parse(await readJson(res)).run;
}

export function runEventsUrl(runId: string): string {
  return `${API_URL}/api/runs/${encodeURIComponent(runId)}/events`;
}
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { act, cleanup, render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { emptyFunnel, type Evaluation, type Run, type RunFunnel } from "@auto-apply/shared";
import { FakeEventSource } from "../test/fake-event-source";
import { RunPanel } from "./RunPanel";

function aRun(overrides: Partial<Run> = {}): Run {
  return {
    runId: "run-1",
    uid: "demo-user",
    status: "discovering",
    funnel: emptyFunnel(),
    reason: null,
    createdAt: "2026-10-06T12:00:00.000Z",
    updatedAt: "2026-10-06T12:00:00.000Z",
    ...overrides,
  };
}

function anEvaluation(jobId: string, overrides: Partial<Evaluation> = {}): Evaluation {
  return {
    jobKey: `greenhouse:acme:${jobId}`,
    runId: "run-1",
    posting: {
      ats: "greenhouse",
      board: "acme",
      jobId,
      title: `Engineer ${jobId}`,
      company: "Acme",
      location: "Remote",
      descriptionText: "Build things.",
      applyUrl: `https://boards.greenhouse.io/acme/jobs/${jobId}`,
    },
    status: "queued",
    verdict: null,
    score: null,
    reason: null,
    createdAt: "2026-10-06T12:00:00.000Z",
    updatedAt: "2026-10-06T12:00:00.000Z",
    ...overrides,
  };
}

function funnel(counts: Partial<RunFunnel>): RunFunnel {
  return { ...emptyFunnel(), ...counts };
}

/** A fake API: the active Run on load, and what `POST /api/runs` answers. */
function fakeApi({
  active = null,
  post = new Response(JSON.stringify({ runId: "run-1" }), { status: 202 }),
}: { active?: Run | null; post?: Response } = {}) {
  const fetchMock = vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = String(input);
    if (url.endsWith("/api/runs/active")) {
      return new Response(JSON.stringify({ run: active }), { status: 200 });
    }
    if (url.endsWith("/api/runs") && init?.method === "POST") return post;
    return new Response("not found", { status: 404 });
  });
  vi.stubGlobal("fetch", fetchMock);
  return fetchMock;
}

/** The value shown for a funnel count or status, found by its label. */
function valueOf(label: string | RegExp): string | null {
  const term = screen.getByText(label, { selector: "dt" });
  return term.nextElementSibling?.textContent ?? null;
}

beforeEach(() => {
  FakeEventSource.instances = [];
  vi.stubGlobal("EventSource", FakeEventSource);
});

afterEach(() => {
  cleanup();
  vi.unstubAllGlobals();
});

describe("<RunPanel />", () => {
  it("starts a Run on click and opens its stream with credentials", async () => {
    const fetchMock = fakeApi();
    render(<RunPanel />);

    await userEvent.click(await screen.findByRole("button", { name: /auto-apply/i }));

    expect(fetchMock).toHaveBeenCalledWith(
      expect.stringMatching(/\/api\/runs$/),
      expect.objectContaining({ method: "POST" }),
    );
    await waitFor(() => expect(FakeEventSource.instances).toHaveLength(1));
    expect(FakeEventSource.latest().url).toMatch(/\/api\/runs\/run-1\/events$/);
    expect(FakeEventSource.latest().withCredentials).toBe(true);
    expect(screen.getByText(/connecting/i)).toBeInTheDocument();
  });

  it("renders the live Run status and funnel counts as events arrive", async () => {
    fakeApi();
    render(<RunPanel />);
    await userEvent.click(await screen.findByRole("button", { name: /auto-apply/i }));
    await waitFor(() => expect(FakeEventSource.instances).toHaveLength(1));
    const stream = FakeEventSource.latest();

    act(() => stream.emit("snapshot", { run: aRun(), evaluations: [] }));
    expect(valueOf("Status")).toBe("Discovering");
    expect(screen.getByText(/live/i)).toBeInTheDocument();

    act(() => {
      stream.emit("eval", anEvaluation("1"));
      stream.emit("run", aRun({ status: "evaluating", funnel: funnel({ discovered: 1 }) }));
      stream.emit("eval", anEvaluation("1", { status: "skipped", reason: "not a fit" }));
    });
    expect(valueOf("Status")).toBe("Evaluating");
    expect(valueOf("Discovered")).toBe("1");
    expect(screen.getByText("Engineer 1")).toBeInTheDocument();
    expect(screen.getByText(/skipped/i, { selector: "li *" })).toBeInTheDocument();
    expect(screen.getByText(/not a fit/)).toBeInTheDocument();
  });

  it("keeps the button disabled while the Run is active, and closes the stream on done", async () => {
    fakeApi();
    render(<RunPanel />);
    const button = await screen.findByRole("button", { name: /auto-apply/i });
    await userEvent.click(button);
    await waitFor(() => expect(FakeEventSource.instances).toHaveLength(1));
    const stream = FakeEventSource.latest();

    act(() => stream.emit("snapshot", { run: aRun(), evaluations: [] }));
    expect(button).toBeDisabled();

    act(() => {
      stream.emit("run", aRun({ status: "completed", funnel: funnel({ submitted: 2 }) }));
      stream.emit("done", { runId: "run-1", status: "completed" });
    });
    expect(valueOf("Status")).toBe("Completed");
    expect(valueOf(/submitted \(simulated\)/i)).toBe("2");
    expect(stream.readyState).toBe(FakeEventSource.CLOSED);
    expect(button).toBeEnabled();
  });

  it("reattaches to the active Run after a page refresh, from a full snapshot", async () => {
    fakeApi({ active: aRun({ status: "evaluating" }) });
    render(<RunPanel />);

    await waitFor(() => expect(FakeEventSource.instances).toHaveLength(1));
    expect(FakeEventSource.latest().url).toMatch(/\/api\/runs\/run-1\/events$/);
    act(() =>
      FakeEventSource.latest().emit("snapshot", {
        run: aRun({ status: "evaluating", funnel: funnel({ discovered: 2, evaluated: 1 }) }),
        evaluations: [anEvaluation("1", { status: "skipped" }), anEvaluation("2")],
      }),
    );

    expect(valueOf("Status")).toBe("Evaluating");
    expect(valueOf("Evaluated")).toBe("1");
    expect(screen.getAllByRole("listitem")).toHaveLength(2);
  });

  it("shows reconnecting when the connection drops, and re-renders from the next snapshot", async () => {
    fakeApi({ active: aRun() });
    render(<RunPanel />);
    await waitFor(() => expect(FakeEventSource.instances).toHaveLength(1));
    const stream = FakeEventSource.latest();
    act(() => stream.emit("snapshot", { run: aRun(), evaluations: [anEvaluation("1")] }));

    act(() => stream.drop());
    expect(screen.getByText(/reconnecting/i)).toBeInTheDocument();

    act(() =>
      stream.emit("snapshot", {
        run: aRun({ status: "applying" }),
        evaluations: [anEvaluation("1", { status: "skipped" }), anEvaluation("2")],
      }),
    );
    expect(valueOf("Status")).toBe("Applying");
    expect(screen.getAllByRole("listitem")).toHaveLength(2);
  });

  it("attaches to the already-active Run when the API answers 409", async () => {
    fakeApi({
      post: new Response(
        JSON.stringify({ error: { code: "run_active", message: "A run is already in progress" } }),
        { status: 409 },
      ),
    });
    render(<RunPanel />);
    const button = await screen.findByRole("button", { name: /auto-apply/i });
    // The Run started elsewhere (another tab) after this page loaded.
    fakeApi({
      active: aRun({ runId: "run-9" }),
      post: new Response(
        JSON.stringify({ error: { code: "run_active", message: "A run is already in progress" } }),
        { status: 409 },
      ),
    });

    await userEvent.click(button);

    await waitFor(() => expect(FakeEventSource.instances).toHaveLength(1));
    expect(FakeEventSource.latest().url).toMatch(/\/api\/runs\/run-9\/events$/);
  });

  it("says so when the API answers 409 but the other Run has already finished", async () => {
    fakeApi({
      active: null,
      post: new Response(
        JSON.stringify({ error: { code: "run_active", message: "A run is already in progress" } }),
        { status: 409 },
      ),
    });
    render(<RunPanel />);

    await userEvent.click(await screen.findByRole("button", { name: /auto-apply/i }));

    expect(await screen.findByRole("alert")).toHaveTextContent(/finished.*try again/i);
    expect(FakeEventSource.instances).toHaveLength(0);
  });

  it("shows an error when the Run cannot be started", async () => {
    fakeApi({ post: new Response("boom", { status: 500 }) });
    render(<RunPanel />);

    await userEvent.click(await screen.findByRole("button", { name: /auto-apply/i }));

    expect(await screen.findByRole("alert")).toHaveTextContent(/500/);
    expect(FakeEventSource.instances).toHaveLength(0);
  });

  it("surfaces a server error event", async () => {
    fakeApi({ active: aRun() });
    render(<RunPanel />);
    await waitFor(() => expect(FakeEventSource.instances).toHaveLength(1));

    act(() =>
      FakeEventSource.latest().emit("error", {
        error: { code: "subscription_error", message: "listener failed" },
      }),
    );

    expect(screen.getByRole("alert")).toHaveTextContent(/listener failed/);
  });
});
/**
 * The Auto-apply button and the live Run view (D20). On load it reattaches to
 * the user's active Run, so a refresh mid-Run loses nothing; the button starts
 * a new Run and stays disabled while one is active (the API's 409 backs it up).
 */
import { useEffect, useState } from "react";
import { isRunActive, type RunFunnel, type RunStatus } from "@auto-apply/shared";
import { ApiError, getActiveRun, startRun } from "../api";
import { useRunStream, type Connection } from "./useRunStream";

const statusLabels: Record<RunStatus, string> = {
  discovering: "Discovering",
  evaluating: "Evaluating",
  applying: "Applying",
  completed: "Completed",
  failed: "Failed",
};

const connectionLabels: Record<Connection, string> = {
  connecting: "Connecting…",
  live: "Live",
  reconnecting: "Reconnecting…",
  closed: "Closed",
};

const funnelLabels: [keyof RunFunnel, string][] = [
  ["discovered", "Discovered"],
  ["evaluated", "Evaluated"],
  ["blocked", "Blocked"],
  ["skipped", "Skipped"],
  ["held", "Held (needs you)"],
  ["submitted", "Submitted (simulated)"],
  ["failed", "Failed"],
];

function messageOf(err: unknown): string {
  return err instanceof Error ? err.message : "Unknown error";
}

export function RunPanel() {
  const [runId, setRunId] = useState<string | null>(null);
  const [checking, setChecking] = useState(true);
  const [starting, setStarting] = useState(false);
  const [startError, setStartError] = useState<string | null>(null);
  const stream = useRunStream(runId);

  useEffect(() => {
    let cancelled = false;
    getActiveRun()
      .then((run) => {
        if (!cancelled && run) setRunId(run.runId);
      })
      .catch((err: unknown) => {
        if (!cancelled) setStartError(`Could not load the active run: ${messageOf(err)}`);
      })
      .finally(() => {
        if (!cancelled) setChecking(false);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  async function onAutoApply() {
    setStarting(true);
    setStartError(null);
    try {
      setRunId(await startRun());
    } catch (err) {
      if (err instanceof ApiError && err.code === "run_active") {
        // Started elsewhere (another tab): follow that Run instead.
        try {
          const active = await getActiveRun();
          if (active) setRunId(active.runId);
          else setStartError("The other run has just finished. Try again.");
        } catch (lookupErr) {
          setStartError(`Could not load the active run: ${messageOf(lookupErr)}`);
        }
      } else {
        setStartError(`Could not start a run: ${messageOf(err)}`);
      }
    } finally {
      setStarting(false);
    }
  }

  const { run } = stream;
  // Waiting for the first snapshot counts as active, so a double click cannot
  // slip in between POST and stream.
  const runActive = run ? isRunActive(run.status) : runId !== null;

  return (
    <section aria-label="Auto-apply">
      <button type="button" onClick={onAutoApply} disabled={checking || starting || runActive}>
        {starting ? "Starting…" : "Auto-apply"}
      </button>
      <p>Submissions are simulated: payloads are built and stored, never sent.</p>

      {startError && <p role="alert">{startError}</p>}
      {stream.error && <p role="alert">Stream error: {stream.error}</p>}

      {runId && (
        <div>
          <p>Connection: {connectionLabels[stream.connection]}</p>
          {!run ? (
            <p role="status">Loading run…</p>
          ) : (
            <>
              <dl>
                <dt>Status</dt>
                <dd>{statusLabels[run.status]}</dd>
                {run.reason && (
                  <>
                    <dt>Reason</dt>
                    <dd>{run.reason}</dd>
                  </>
                )}
                {funnelLabels.map(([key, label]) => (
                  <div key={key}>
                    <dt>{label}</dt>
                    <dd>{run.funnel[key]}</dd>
                  </div>
                ))}
              </dl>
              {stream.evaluations.length === 0 ? (
                <p>No jobs yet.</p>
              ) : (
                <ul>
                  {stream.evaluations.map((evaluation) => (
                    <li key={evaluation.jobKey}>
                      <strong>{evaluation.posting.title}</strong> at {evaluation.posting.company}:{" "}
                      <span>{evaluation.status}</span>
                      {evaluation.reason && <span> ({evaluation.reason})</span>}
                    </li>
                  ))}
                </ul>
              )}
            </>
          )}
        </div>
      )}
    </section>
  );
}
/**
 * The one place the browser holds a Run's live stream (CODING_STANDARDS, Web).
 * It opens an `EventSource` with credentials, parses every event with the
 * contract's schemas, and closes on `done`, on unmount, or when the run id
 * changes. State is always the latest the server sent (ADR-0003): a `snapshot`
 * replaces everything, so a reconnect re-renders from scratch and loses nothing.
 */
import { useEffect, useState } from "react";
import {
  doneEventSchema,
  errorEventSchema,
  evalEventSchema,
  runEventSchema,
  snapshotEventSchema,
  type Evaluation,
  type Run,
} from "@auto-apply/shared";
import { runEventsUrl } from "../api";

export type Connection = "connecting" | "live" | "reconnecting" | "closed";

export interface RunStreamState {
  connection: Connection;
  run: Run | null;
  /** The latest Evaluation per Job Key, in the order they first appeared. */
  evaluations: Evaluation[];
  error: string | null;
}

const initial: RunStreamState = {
  connection: "connecting",
  run: null,
  evaluations: [],
  error: null,
};

function upsert(evaluations: Evaluation[], next: Evaluation): Evaluation[] {
  const i = evaluations.findIndex((e) => e.jobKey === next.jobKey);
  if (i === -1) return [...evaluations, next];
  return evaluations.map((e, j) => (j === i ? next : e));
}

export function useRunStream(runId: string | null): RunStreamState {
  const [state, setState] = useState<RunStreamState>(initial);

  useEffect(() => {
    setState(initial);
    if (!runId) return;

    const source = new EventSource(runEventsUrl(runId), { withCredentials: true });

    /** Parses one event's JSON; a malformed one is reported, never trusted. */
    const handle =
      <T>(parse: (data: unknown) => T, apply: (prev: RunStreamState, data: T) => RunStreamState) =>
      (event: Event) => {
        let data: T;
        try {
          data = parse(JSON.parse((event as MessageEvent<string>).data));
        } catch {
          setState((prev) => ({ ...prev, error: `Malformed ${event.type} event from the server` }));
          return;
        }
        setState((prev) => apply(prev, data));
      };

    source.addEventListener(
      "snapshot",
      handle(snapshotEventSchema.parse, (_prev, { run, evaluations }) => ({
        connection: "live",
        run,
        evaluations,
        error: null,
      })),
    );
    source.addEventListener(
      "run",
      handle(runEventSchema.parse, (prev, run) => ({ ...prev, run })),
    );
    source.addEventListener(
      "eval",
      handle(evalEventSchema.parse, (prev, evaluation) => ({
        ...prev,
        evaluations: upsert(prev.evaluations, evaluation),
      })),
    );
    const onDone = handle(doneEventSchema.parse, (prev) => ({
      ...prev,
      connection: "closed" as const,
    }));
    source.addEventListener("done", (event) => {
      // The server ends the response next; without close() the browser would
      // reconnect and stream the finished Run again.
      source.close();
      onDone(event);
    });
    // `error` is both the server's named event (it carries data) and the
    // browser's own connection-error signal (it does not).
    source.addEventListener("error", (event) => {
      if (event instanceof MessageEvent) {
        handle(errorEventSchema.parse, (prev, { error }) => ({ ...prev, error: error.message }))(
          event,
        );
        return;
      }
      setState((prev) => ({
        ...prev,
        connection: source.readyState === EventSource.CLOSED ? "closed" : "reconnecting",
      }));
    });

    return () => source.close();
  }, [runId]);

  return state;
}
