/**
 * The Auto-apply button and the live Run view (D20). On load it reattaches to
 * the user's active Run, so a refresh mid-Run loses nothing; the button starts
 * a new Run and stays disabled while one is active (the API's 409 backs it up).
 */
import { useEffect, useState } from "react";
import { isRunActive, type RunFunnel, type RunStatus } from "@auto-apply/shared";
import { ApiError, getActiveRun, startRun } from "../api";
import { useRunStream, type Connection } from "./useRunStream";

const statusLabels: Record<RunStatus, string> = {
  discovering: "Discovering",
  evaluating: "Evaluating",
  applying: "Applying",
  completed: "Completed",
  failed: "Failed",
};

const connectionLabels: Record<Connection, string> = {
  connecting: "Connecting…",
  live: "Live",
  reconnecting: "Reconnecting…",
  closed: "Closed",
};

const funnelLabels: [keyof RunFunnel, string][] = [
  ["discovered", "Discovered"],
  ["evaluated", "Evaluated"],
  ["blocked", "Blocked"],
  ["skipped", "Skipped"],
  ["held", "Held (needs you)"],
  ["submitted", "Submitted (simulated)"],
  ["failed", "Failed"],
];

function messageOf(err: unknown): string {
  return err instanceof Error ? err.message : "Unknown error";
}

export function RunPanel() {
  const [runId, setRunId] = useState<string | null>(null);
  const [checking, setChecking] = useState(true);
  const [starting, setStarting] = useState(false);
  const [startError, setStartError] = useState<string | null>(null);
  const stream = useRunStream(runId);

  useEffect(() => {
    let cancelled = false;
    getActiveRun()
      .then((run) => {
        if (!cancelled && run) setRunId(run.runId);
      })
      .catch((err: unknown) => {
        if (!cancelled) setStartError(`Could not load the active run: ${messageOf(err)}`);
      })
      .finally(() => {
        if (!cancelled) setChecking(false);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  async function onAutoApply() {
    setStarting(true);
    setStartError(null);
    try {
      setRunId(await startRun());
    } catch (err) {
      if (err instanceof ApiError && err.code === "run_active") {
        // Started elsewhere (another tab): follow that Run instead.
        try {
          const active = await getActiveRun();
          if (active) setRunId(active.runId);
          else setStartError("The other run has just finished. Try again.");
        } catch (lookupErr) {
          setStartError(`Could not load the active run: ${messageOf(lookupErr)}`);
        }
      } else {
        setStartError(`Could not start a run: ${messageOf(err)}`);
      }
    } finally {
      setStarting(false);
    }
  }

  const { run } = stream;
  // Waiting for the first snapshot counts as active, so a double click cannot
  // slip in between POST and stream.
  const runActive = run ? isRunActive(run.status) : runId !== null;

  return (
    <section aria-label="Auto-apply">
      <button type="button" onClick={onAutoApply} disabled={checking || starting || runActive}>
        {starting ? "Starting…" : "Auto-apply"}
      </button>
      <p>Submissions are simulated: payloads are built and stored, never sent.</p>

      {startError && <p role="alert">{startError}</p>}
      {stream.error && <p role="alert">Stream error: {stream.error}</p>}

      {runId && (
        <div>
          <p>Connection: {connectionLabels[stream.connection]}</p>
          {!run ? (
            <p role="status">Loading run…</p>
          ) : (
            <>
              <dl>
                <dt>Status</dt>
                <dd>{statusLabels[run.status]}</dd>
                {run.reason && (
                  <>
                    <dt>Reason</dt>
                    <dd>{run.reason}</dd>
                  </>
                )}
                {funnelLabels.map(([key, label]) => (
                  <div key={key}>
                    <dt>{label}</dt>
                    <dd>{run.funnel[key]}</dd>
                  </div>
                ))}
              </dl>
              {stream.evaluations.length === 0 ? (
                <p>No jobs yet.</p>
              ) : (
                <ul>
                  {stream.evaluations.map((evaluation) => (
                    <li key={evaluation.jobKey}>
                      <strong>{evaluation.posting.title}</strong> at {evaluation.posting.company}:{" "}
                      <span>{evaluation.status}</span>
                      {evaluation.reason && <span> ({evaluation.reason})</span>}
                    </li>
                  ))}
                </ul>
              )}
            </>
          )}
        </div>
      )}
    </section>
  );
}
/**
 * The one place the browser holds a Run's live stream (CODING_STANDARDS, Web).
 * It opens an `EventSource` with credentials, parses every event with the
 * contract's schemas, and closes on `done`, on unmount, or when the run id
 * changes. State is always the latest the server sent (ADR-0003): a `snapshot`
 * replaces everything, so a reconnect re-renders from scratch and loses nothing.
 */
import { useEffect, useState } from "react";
import {
  doneEventSchema,
  errorEventSchema,
  evalEventSchema,
  runEventSchema,
  snapshotEventSchema,
  type Evaluation,
  type Run,
} from "@auto-apply/shared";
import { runEventsUrl } from "../api";

export type Connection = "connecting" | "live" | "reconnecting" | "closed";

export interface RunStreamState {
  connection: Connection;
  run: Run | null;
  /** The latest Evaluation per Job Key, in the order they first appeared. */
  evaluations: Evaluation[];
  error: string | null;
}

const initial: RunStreamState = {
  connection: "connecting",
  run: null,
  evaluations: [],
  error: null,
};

function upsert(evaluations: Evaluation[], next: Evaluation): Evaluation[] {
  const i = evaluations.findIndex((e) => e.jobKey === next.jobKey);
  if (i === -1) return [...evaluations, next];
  return evaluations.map((e, j) => (j === i ? next : e));
}

export function useRunStream(runId: string | null): RunStreamState {
  const [state, setState] = useState<RunStreamState>(initial);

  useEffect(() => {
    setState(initial);
    if (!runId) return;

    const source = new EventSource(runEventsUrl(runId), { withCredentials: true });

    /** Parses one event's JSON; a malformed one is reported, never trusted. */
    const handle =
      <T>(parse: (data: unknown) => T, apply: (prev: RunStreamState, data: T) => RunStreamState) =>
      (event: Event) => {
        let data: T;
        try {
          data = parse(JSON.parse((event as MessageEvent<string>).data));
        } catch {
          setState((prev) => ({ ...prev, error: `Malformed ${event.type} event from the server` }));
          return;
        }
        setState((prev) => apply(prev, data));
      };

    source.addEventListener(
      "snapshot",
      handle(snapshotEventSchema.parse, (_prev, { run, evaluations }) => ({
        connection: "live",
        run,
        evaluations,
        error: null,
      })),
    );
    source.addEventListener(
      "run",
      handle(runEventSchema.parse, (prev, run) => ({ ...prev, run })),
    );
    source.addEventListener(
      "eval",
      handle(evalEventSchema.parse, (prev, evaluation) => ({
        ...prev,
        evaluations: upsert(prev.evaluations, evaluation),
      })),
    );
    const onDone = handle(doneEventSchema.parse, (prev) => ({
      ...prev,
      connection: "closed" as const,
    }));
    source.addEventListener("done", (event) => {
      // The server ends the response next; without close() the browser would
      // reconnect and stream the finished Run again.
      source.close();
      onDone(event);
    });
    // `error` is both the server's named event (it carries data) and the
    // browser's own connection-error signal (it does not).
    source.addEventListener("error", (event) => {
      if (event instanceof MessageEvent) {
        handle(errorEventSchema.parse, (prev, { error }) => ({ ...prev, error: error.message }))(
          event,
        );
        return;
      }
      setState((prev) => ({
        ...prev,
        connection: source.readyState === EventSource.CLOSED ? "closed" : "reconnecting",
      }));
    });

    return () => source.close();
  }, [runId]);

  return state;
}
import { describe, it, expect, vi, afterEach } from "vitest";
import { render, screen, waitFor, cleanup } from "@testing-library/react";
import { App } from "./App";

/** Answers `/api/health` with `response`; the Run panel sees no active Run. */
function mockFetch(response: Response) {
  vi.stubGlobal(
    "fetch",
    vi.fn(async (input: RequestInfo | URL) =>
      String(input).endsWith("/api/runs/active")
        ? new Response(JSON.stringify({ run: null }), { status: 200 })
        : response,
    ),
  );
}

afterEach(() => {
  cleanup();
  vi.unstubAllGlobals();
});

describe("<App />", () => {
  it("shows a loading state, then the health data on success", async () => {
    mockFetch(
      new Response(
        JSON.stringify({
          status: "ok",
          service: "auto-apply-api",
          namespace: "dev",
          repo: "memory",
          time: new Date().toISOString(),
        }),
        { status: 200, headers: { "Content-Type": "application/json" } },
      ),
    );

    render(<App />);
    expect(screen.getByRole("status")).toBeInTheDocument();

    await waitFor(() => expect(screen.getByText("dev")).toBeInTheDocument());
    expect(screen.queryByRole("status")).not.toBeInTheDocument();
    // ADR-0004: an in-memory store is called out, never mistaken for persistence.
    expect(screen.getByText(/in-memory \(not persisted\)/i)).toBeInTheDocument();
  });

  it("shows an error state when the API responds with a failure", async () => {
    mockFetch(new Response("boom", { status: 500 }));

    render(<App />);

    await waitFor(() => expect(screen.getByRole("alert")).toBeInTheDocument());
    expect(screen.getByRole("alert")).toHaveTextContent("500");
  });
});
import "@testing-library/jest-dom/vitest";
/**
 * A stand-in for the browser's `EventSource` (spec, UI seam): tests push
 * contract-shaped server events into it and inspect how it was opened and
 * whether it was closed.
 */
export class FakeEventSource extends EventTarget {
  static readonly CONNECTING = 0;
  static readonly OPEN = 1;
  static readonly CLOSED = 2;
  static instances: FakeEventSource[] = [];

  readyState = FakeEventSource.CONNECTING;
  readonly withCredentials: boolean;

  constructor(
    readonly url: string,
    init?: EventSourceInit,
  ) {
    super();
    this.withCredentials = init?.withCredentials ?? false;
    FakeEventSource.instances.push(this);
  }

  /** The most recently opened stream. */
  static latest(): FakeEventSource {
    const latest = FakeEventSource.instances.at(-1);
    if (!latest) throw new Error("no EventSource was opened");
    return latest;
  }

  /** The server sends a named event with a JSON payload. */
  emit(event: string, data: unknown): void {
    this.readyState = FakeEventSource.OPEN;
    this.dispatchEvent(new MessageEvent(event, { data: JSON.stringify(data) }));
  }

  /** The connection drops; the browser will retry (`reconnecting`) unless closed. */
  drop(): void {
    this.readyState = FakeEventSource.CONNECTING;
    this.dispatchEvent(new Event("error"));
  }

  close(): void {
    this.readyState = FakeEventSource.CLOSED;
  }
}

