            value={current}
            aria-label="Views"
            variant="scrollable"
            scrollButtons={false}
            sx={{ minHeight: 40, mt: -1 }}
          >
            {navItems.map((item) => (
              <Tab
                key={item.path}
                label={item.label}
                value={item.path}
                component={Link}
                to={item.path}
                sx={{ minHeight: 40, px: 1.5 }}
              />
            ))}
          </Tabs>
        </Container>
      </AppBar>

      <Container component="main" maxWidth="lg" sx={{ flex: 1, py: 4 }}>
        {children}
      </Container>

      <Box component="footer" sx={{ borderTop: 1, borderColor: "divider", py: 2 }}>
        <Container maxWidth="lg">
          <Stack
