import Toolbar from "@mui/material/Toolbar";
import Typography from "@mui/material/Typography";
import AutoAwesomeIcon from "@mui/icons-material/AutoAwesome";
import { ApiHealth } from "./ApiHealth";

export const navItems = [
  { path: "/", label: "Run" },
  { path: "/applied", label: "Applied jobs" },
  { path: "/scanned", label: "Scanned jobs" },
  { path: "/settings", label: "Settings" },
] as const;

export function AppShell({ children }: { children: ReactNode }) {
  const { pathname } = useLocation();
  const current = navItems.find((item) => item.path === pathname)?.path ?? false;

  return (
    <Box sx={{ minHeight: "100vh", display: "flex", flexDirection: "column" }}>
      <AppBar position="sticky">
        <Container maxWidth="lg">
          <Toolbar disableGutters sx={{ gap: 2, minHeight: { xs: 56 } }}>
            <Stack direction="row" spacing={1} sx={{ alignItems: "center", flexShrink: 0 }}>
              <AutoAwesomeIcon color="primary" fontSize="small" aria-hidden="true" />
              <Typography component="span" sx={{ fontWeight: 700 }}>
                AI Auto-apply
              </Typography>
              <Chip label="Prototype" size="small" variant="outlined" />
            </Stack>
          </Toolbar>
          <Tabs
            value={current}
            aria-label="Views"
            variant="scrollable"
            scrollButtons={false}
            sx={{ minHeight: 40, mt: -1 }}
          >
            {navItems.map((item) => (
              <Tab
                key={item.path}
                label={item.label}
                value={item.path}
                component={Link}
                to={item.path}
                sx={{ minHeight: 40, px: 1.5 }}
              />
            ))}
          </Tabs>
        </Container>
      </AppBar>

      <Container component="main" maxWidth="lg" sx={{ flex: 1, py: 4 }}>
        {children}
      </Container>

      <Box component="footer" sx={{ borderTop: 1, borderColor: "divider", py: 2 }}>
        <Container maxWidth="lg">
          <Stack
            direction={{ xs: "column", sm: "row" }}
            spacing={1}
            sx={{ justifyContent: "space-between" }}
          >
            <Typography variant="caption" color="text.secondary">
              Submissions are simulated · payloads are built and stored, never sent
            </Typography>
            <ApiHealth />
          </Stack>
        </Container>
      </Box>
    </Box>
  );
}

/**
 * A view whose ticket has not landed yet (Applied jobs: 11, Scanned jobs and
 * Settings: 12). It says so plainly instead of showing an empty list that looks
 * like real data.
 */
import Card from "@mui/material/Card";
import CardContent from "@mui/material/CardContent";
import Stack from "@mui/material/Stack";
import Typography from "@mui/material/Typography";

export function PlaceholderPage({ title, description }: { title: string; description: string }) {
  return (
    <Stack spacing={3}>
      <Typography variant="h1">{title}</Typography>
      <Card>
        <CardContent sx={{ py: 6, textAlign: "center" }}>
          <Typography variant="h3" gutterBottom>
            Not built yet
          </Typography>
          <Typography color="text.secondary">{description}</Typography>
        </CardContent>
      </Card>
    </Stack>
  );
}

/**
 * The themed shell and the routed views (D20). The router itself is provided
 * by the caller (`BrowserRouter` in `main.tsx`, `MemoryRouter` in tests).
 */
import { Navigate, Route, Routes } from "react-router-dom";
import CssBaseline from "@mui/material/CssBaseline";
import { ThemeProvider } from "@mui/material/styles";
import { theme } from "./theme";
import { AppShell } from "./shell/AppShell";
import { RunPanel } from "./run/RunPanel";
import { PlaceholderPage } from "./pages/PlaceholderPage";

export function App() {
  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <AppShell>
        <Routes>
          <Route path="/" element={<RunPanel />} />
          <Route
            path="/applied"
            element={
              <PlaceholderPage
                title="Applied jobs"
                description="Each simulated submission and the payload built for it will be listed here."
              />
            }
          />
          <Route
            path="/scanned"
            element={
              <PlaceholderPage
                title="Scanned jobs"
                description="Every job evaluated across runs, with its verdict and reason, will be listed here."
              />
            }
          />
          <Route
            path="/settings"
            element={
              <PlaceholderPage
                title="Settings"
                description="The profile, preferences and settings that drive matching will be shown here."
              />
            }
          />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </AppShell>
    </ThemeProvider>
  );
}

